import{_ as a,o,c as l,ag as r}from"./chunks/framework.DWOJQht4.js";const u=JSON.parse('{"title":"Docker 部署","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/docker.md","filePath":"deployment/docker.md","lastUpdated":1792597117000}'),t={name:"deployment/docker.md"};function i(d,e,c,s,n,p){return o(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="docker-部署" tabindex="-1">Docker 部署 <a class="header-anchor" href="#docker-部署" aria-label="Permalink to &quot;Docker 部署&quot;">​</a></h1><p>当前文档体系已不再将 Docker 作为 <strong>平台主服务</strong> 的推荐生产部署方式。</p><p>也就是说：</p><ul><li>当前没有官方维护的“下载 <code>docker-compose.yml</code> 后直接部署整个平台”的主线文档</li><li>当前没有把 Docker Compose 作为平台主服务默认发布形态</li><li>如果你在别处看到 Compose，通常是在说题目模板、多服务靶场、漏洞环境，而不是主服务本身</li></ul><p>目前主推方案是：</p><ul><li><code>systemd + 单二进制</code></li><li>前端资源内嵌进服务二进制</li><li>数据库按环境选择 SQLite 或 MySQL</li></ul><h2 id="为什么这个页面还保留" tabindex="-1">为什么这个页面还保留？ <a class="header-anchor" href="#为什么这个页面还保留" aria-label="Permalink to &quot;为什么这个页面还保留？&quot;">​</a></h2><p>保留本页仅用于兼容旧链接，避免历史文档或外部引用直接失效。</p><h2 id="什么时候还会用到-docker" tabindex="-1">什么时候还会用到 Docker？ <a class="header-anchor" href="#什么时候还会用到-docker" aria-label="Permalink to &quot;什么时候还会用到 Docker？&quot;">​</a></h2><p>Docker 仍然可能出现在这些场景：</p><ol><li>动态靶机运行时</li><li>漏洞环境模板启动</li><li>某些实验 / 测试环境</li><li>你们内部自定义的容器化封装方案</li></ol><p>但这些都不等于“平台主服务必须用 Docker 部署”。</p><h2 id="当前应该看哪里" tabindex="-1">当前应该看哪里？ <a class="header-anchor" href="#当前应该看哪里" aria-label="Permalink to &quot;当前应该看哪里？&quot;">​</a></h2><ul><li><a href="/CloudCTF/guide/quick-start.html">快速开始</a></li><li><a href="/CloudCTF/guide/architecture.html">技术架构</a></li><li><a href="/CloudCTF/guide/faq.html">常见问题</a></li></ul>',14)])])}const k=a(t,[["render",i]]);export{u as __pageData,k as default};
